def transform(grid):
    out = [row[:] for row in grid]
    points = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 2]
    # The main axis is the row containing the pair of horizontal endpoints.
    rows = {}
    for r, c in points:
        rows.setdefault(r, []).append(c)
    axis = max(rows, key=lambda r: len(rows[r]))
    lo, hi = min(rows[axis]), max(rows[axis])
    for c in range(lo + 1, hi):
        if out[axis][c] == 0:
            out[axis][c] = 3
    # Connect every off-axis point to the main horizontal axis in its column.
    for r, c in points:
        if r == axis:
            continue
        step = 1 if axis > r else -1
        rr = r + step
        while rr != axis:
            if out[rr][c] == 0:
                out[rr][c] = 3
            rr += step
    return out
